-- BEGIN BUNDLED LIBRARIES (tools/bundle_libs.py)
-- Generated by tools/bundle_libs.py — do not edit by hand. Regenerate with: python3 tools/bundle_libs.py
local __LIBS = {}
local __LOADERS = {}
-- Forward declaration: libraries call require_lib at load time.
local require_lib

__LOADERS["bysekoze"] = function(...)
-- =====================================================================
-- Lib: bysekoze — цепочка доступа Byse (filemoon-клон):
--      details -> access/challenge -> access/attest (ECDSA P-256) ->
--      embed/captcha (PoW) -> captcha/verify -> embed/playback ->
--      AES-256-GCM -> sources[].url.
-- Loaded via require_lib("bysekoze"). No dependencies on other libs.
--
-- Живой сквозной прогон 2026-10-10 (Node/curl, код fsjcjqhnhtph):
--   details 200 -> challenge 200 -> attest 200 (confidence 0.45..0.7) ->
--   captcha 200 (pow_difficulty 16) -> verify 200 -> playback 200 ->
--   decrypt -> master.m3u8 -> 200 application/vnd.apple.mpegurl.
-- Все URL/тела/заголовки ниже — те же, что в этом прогоне.
-- UA не хардкодим: заголовки подставляет движок (UserAgentInterceptor /
-- дефолтный header тестера), а client.user_agent в attest подписываем
-- значением get_user_agent() — тем же байт-в-байт.
-- Телеметрию (view/heartbeat/timeslider/settings) не реализуем.
-- =====================================================================
local version = "1.0.0"

local M = {}

-- Бюджет запросов: origin-iframe за CF, авто-обход ждёт до 15с.
local EMBED_TIMEOUT = 22000
local SITE = "https://bysekoze.com"

-- ── JSON-тела вручную (движок отдаёт json_encode только как опцию; тела
--    ниже — фиксированный набор полей, сериализация тривиальна). ──────────
local function jstr(s)
    local esc = tostring(s):gsub('([\\"])', '\\%0')
    return '"' .. esc .. '"'
end

-- fingerprint из ответа attest; confidence пересылаем как сырой числовой
-- текст из ответа — без повторного форматирования числа.
local function fingerprintJson(fp)
    local s = '{"token":' .. jstr(fp.token)
        .. ',"viewer_id":' .. jstr(fp.viewer_id)
        .. ',"device_id":' .. jstr(fp.device_id)
    if fp.confidence then s = s .. ',"confidence":' .. fp.confidence end
    return s .. '}'
end

-- ── PoW: решает движок — pow_solve (PowSolver.kt, тот же gr/wr, что в
--    JS-бандле origin-iframe; ~1с на difficulty 16).
--
--    Чистого-Lua решателя здесь НЕТ сознательно: порт gr() на LuaJ даёт
--    ~150 хэшей/с (замер 2026-10-10; lua CLI — ~540/с), а реальные
--    решения уходят в 35k..150k итераций — это минуты блокировки вместо
--    секунды на JVM. Оба движка (Dreamora LuaSourceLoader.kt и
--    plugin-tester) обязаны регистрировать pow_solve. ─────────────────────
function M.solvePow(nonce, difficulty)
    if type(pow_solve) ~= "function" then
        log_error("bysekoze: pow_solve unavailable")
        return nil
    end
    local ok, sol = pcall(pow_solve, nonce, difficulty)
    if not ok then
        log_error("bysekoze: pow_solve failed: " .. tostring(sol))
        return nil
    end
    if type(sol) ~= "string" and type(sol) ~= "number" then
        log_error("bysekoze: pow_solve returned " .. type(sol)
            .. " (difficulty " .. tostring(difficulty) .. ")")
        return nil
    end
    return tostring(sol)
end

-- ── Дешифровка playback: key = key_parts[version] .. key_parts[31-version]
--    (1-based; так же делает Qa()/ws() в JS, версии 1..20). ───────────────
local function decryptPlayback(body)
    local obj = body:match('"playback"%s*:%s*(%b{})')
    if not obj then
        log_error("bysekoze: no playback object, head=" .. body:sub(1, 200))
        return nil
    end
    local ivB64 = obj:match('"iv"%s*:%s*"([^"]+)"')
    local payloadB64 = obj:match('"payload"%s*:%s*"([^"]+)"')
    local version = tonumber(obj:match('"version"%s*:%s*"?([%d]+)"?'))
    local arr = obj:match('"key_parts"%s*:%s*(%b[])')
    if not ivB64 or not payloadB64 or not arr then
        log_error("bysekoze: playback misses iv/payload/key_parts")
        return nil
    end
    local parts = {}
    for p in arr:gmatch('"([^"]+)"') do parts[#parts + 1] = p end

    local i1, i2
    if version and version >= 1 and version <= 20 then
        i1, i2 = version, 31 - version
    end
    if not i1 or not parts[i1] or not parts[i2] then
        log_error("bysekoze: unsupported key version " .. tostring(version)
            .. " (" .. #parts .. " parts)")
        return nil
    end
    if type(aes_gcm_decrypt) ~= "function"
        or type(base64_decode_bytes) ~= "function" then
        log_error("bysekoze: aes_gcm_decrypt/base64_decode_bytes unavailable")
        return nil
    end

    local k1 = base64_decode_bytes(parts[i1])
    local k2 = base64_decode_bytes(parts[i2])
    local iv = base64_decode_bytes(ivB64)
    local payload = base64_decode_bytes(payloadB64)
    if not k1 or not k2 or not iv or not payload or #payload <= 16 then
        local plen = type(payload) == "string" and tostring(#payload) or "nil"
        log_error("bysekoze: bad base64 in playback (parts=" .. #parts
            .. " payload=" .. plen .. "B)")
        return nil
    end
    -- payload = ct .. tag (tag — последние 16 байт).
    local ct = payload:sub(1, #payload - 16)
    local tag = payload:sub(#payload - 15)
    local key = k1 .. k2
    local plain = aes_gcm_decrypt(key, iv, ct, tag)
    if type(plain) ~= "string" or plain == "" then
        log_error("bysekoze: aes_gcm_decrypt failed (key=" .. #key
            .. "B iv=" .. #iv .. "B ct=" .. #ct .. "B)")
        return nil
    end
    return plain
end

-- JSON-строка url приходит экранированной (\u0026 и т.п.). Regex выше
-- берёт сырой текст — без разэкранирования CDN отдаёт 404 по битому
-- query-стрингу (проверено на эмуляторе 2026-10-10: t=...\u0026s=...).
local function jsonUnescape(s)
    local map = { n = "\n", r = "\r", t = "\t", b = "\b", f = "\f" }
    s = s:gsub("\\u(%x%x%x%x)", function(h)
        local cp = tonumber(h, 16)
        if cp < 0x80 then return string.char(cp) end
        if cp < 0x800 then
            return string.char(0xC0 + math.floor(cp / 0x40), 0x80 + cp % 0x40)
        end
        return string.char(0xE0 + math.floor(cp / 0x1000),
            0x80 + math.floor(cp / 0x40) % 0x40, 0x80 + cp % 0x40)
    end)
    s = s:gsub('\\(["\\/bfnrt])', function(c) return map[c] or c end)
    return s
end

-- Первый HLS-источник; остальное (mp4 и пр.) — фоллбэк.
local function pickSource(plain)
    local sources = plain:match('"sources"%s*:%s*(%b[])')
    if not sources then
        log_error("bysekoze: no sources[] in payload, head=" .. plain:sub(1, 200))
        return nil
    end
    local fbUrl, fbMime
    for obj in sources:gmatch('(%b{})') do
        local u = obj:match('"url"%s*:%s*"([^"]+)"')
        local mime = obj:match('"mime_type"%s*:%s*"([^"]+)"')
        if u and u ~= "" then
            u = jsonUnescape(u)
            if u:find(".m3u8", 1, true)
                or (mime and mime:find("mpegurl", 1, true)) then
                return u, "hls"
            end
            if not fbUrl then fbUrl, fbMime = u, mime end
        end
    end
    if not fbUrl then
        log_error("bysekoze: sources[] has no url")
        return nil
    end
    -- ponytail: bysekoze отдаёт HLS (filemoon-клон); mp4 помечаем по mime.
    return fbUrl, (fbMime and fbMime:find("mp4", 1, true)) and "mp4" or "hls"
end

-- embedUrl: https://bysekoze.com/e/{code}
-- Возвращает url, mime ("hls"|"mp4"), ref; nil при любой неудаче шага.
function M.extractBysekoze(embedUrl)
    local code = type(embedUrl) == "string" and embedUrl:match("/e/([%w_-]+)") or nil
    if not code then
        log_error("bysekoze: no /e/{code} in " .. tostring(embedUrl))
        return nil
    end
    local parent = SITE .. "/e/" .. code

    -- Контракт движка: свежий эфемерный P-256 keypair на каждый вызов.
    -- Проверяем сразу, до сетевых шагов.
    if type(ecdsa_sign_p256) ~= "function" then
        log_error("bysekoze: ecdsa_sign_p256 unavailable")
        return nil
    end

    -- 1. details: путь origin-iframe (и сам origin) рандомны на каждый
    --    запрос — только из embed_frame_url, без хардкода.
    local d = http_get(SITE .. "/api/videos/" .. code .. "/embed/details", {
        timeout = EMBED_TIMEOUT,
    })
    if not d or not d.success or type(d.body) ~= "string" then
        log_error("bysekoze: details HTTP " .. tostring(d and d.code))
        return nil
    end
    local frame = d.body:match('"embed_frame_url"%s*:%s*"([^"]+)"')
    local origin = frame and frame:match("^(https?://[^/]+)")
    if not origin then
        log_error("bysekoze: no embed_frame_url (HTTP " .. tostring(d.code)
            .. ") head=" .. d.body:sub(1, 200))
        return nil
    end

    -- Все запросы origin-iframe — с X-Embed-Parent (как в браузере);
    -- User-Agent не трогаем — его подставляет движок.
    local function post(path, body)
        return http_post(origin .. path, body, {
            timeout = EMBED_TIMEOUT,
            headers = {
                ["Content-Type"] = "application/json",
                ["X-Embed-Parent"] = parent,
            },
        })
    end

    -- 2a. challenge
    local c = post("/api/videos/access/challenge", "{}")
    if not c or not c.success or type(c.body) ~= "string" then
        log_error("bysekoze: challenge HTTP " .. tostring(c and c.code)
            .. " " .. tostring(c and c.body and c.body:sub(1, 160)))
        return nil
    end
    local challengeId = c.body:match('"challenge_id"%s*:%s*"([^"]+)"')
    local nonce = c.body:match('"nonce"%s*:%s*"([^"]+)"')
    if not challengeId or not nonce then
        log_error("bysekoze: challenge parse failed head=" .. c.body:sub(1, 200))
        return nil
    end

    -- 2b. attest: свежий эфемерный P-256 keypair на каждый вызов.
    local okSig, sig = pcall(ecdsa_sign_p256, nonce)
    if not okSig or type(sig) ~= "table" or type(sig.signature) ~= "string"
        or type(sig.x) ~= "string" or type(sig.y) ~= "string" then
        log_error("bysekoze: ecdsa_sign_p256 failed: " .. tostring(sig))
        return nil
    end
    -- Минимальный client/storage (так же проходит живой прогон,
    -- confidence 0.45..0.7 — для playback достаточно). client.user_agent —
    -- эффективный UA движка (тот же, что в заголовках http_*); если
    -- get_user_agent не зарегистрирован, поле client опускаем целиком.
    local ua = type(get_user_agent) == "function" and get_user_agent() or nil
    local clientJson = ""
    if type(ua) == "string" and ua ~= "" then
        clientJson = ',"client":{"user_agent":' .. jstr(ua) .. '}'
    end
    local attestBody = '{"viewer_id":"","device_id":""'
        .. ',"challenge_id":' .. jstr(challengeId)
        .. ',"nonce":' .. jstr(nonce)
        .. ',"signature":' .. jstr(sig.signature)
        .. ',"public_key":{"kty":"EC","crv":"P-256","x":' .. jstr(sig.x)
        .. ',"y":' .. jstr(sig.y) .. '}'
        .. clientJson
        .. ',"storage":{},"attributes":{"entropy":"low"}}'
    local a = post("/api/videos/access/attest", attestBody)
    if not a or not a.success or type(a.body) ~= "string" then
        log_error("bysekoze: attest HTTP " .. tostring(a and a.code)
            .. " " .. tostring(a and a.body and a.body:sub(1, 200)))
        return nil
    end
    local fp = {
        token = a.body:match('"token"%s*:%s*"([^"]+)"'),
        viewer_id = a.body:match('"viewer_id"%s*:%s*"([^"]+)"'),
        device_id = a.body:match('"device_id"%s*:%s*"([^"]+)"'),
        confidence = a.body:match('"confidence"%s*:%s*([%d%.eE+-]+)'),
    }
    if not fp.token or not fp.viewer_id or not fp.device_id then
        log_error("bysekoze: attest parse failed head=" .. a.body:sub(1, 200))
        return nil
    end
    local fpJson = fingerprintJson(fp)

    -- 2c. captcha -> PoW challenge
    local cap = post("/api/videos/" .. code .. "/embed/captcha",
        '{"fingerprint":' .. fpJson .. '}')
    if not cap or not cap.success or type(cap.body) ~= "string" then
        log_error("bysekoze: captcha HTTP " .. tostring(cap and cap.code)
            .. " " .. tostring(cap and cap.body and cap.body:sub(1, 160)))
        return nil
    end
    local powNonce = cap.body:match('"pow_nonce"%s*:%s*"([^"]+)"')
    local powToken = cap.body:match('"pow_token"%s*:%s*"([^"]+)"')
    local difficulty = tonumber(cap.body:match('"pow_difficulty"%s*:%s*(%d+)'))
    if not powNonce or not powToken or not difficulty then
        log_error("bysekoze: captcha parse failed head=" .. cap.body:sub(1, 200))
        return nil
    end

    -- 2d. PoW: leadingZeroBits(gr(nonce .. ":" .. n)) >= difficulty.
    local solution = M.solvePow(powNonce, difficulty)
    if not solution then
        log_error("bysekoze: PoW failed (difficulty " .. difficulty .. ")")
        return nil
    end

    -- 2e. verify (solution — СТРОКА, не число: так принимает сервер).
    local v = post("/api/videos/" .. code .. "/embed/captcha/verify",
        '{"pow_token":' .. jstr(powToken)
        .. ',"solution":' .. jstr(solution)
        .. ',"fingerprint":' .. fpJson .. '}')
    if not v or not v.success or type(v.body) ~= "string" then
        log_error("bysekoze: verify HTTP " .. tostring(v and v.code)
            .. " " .. tostring(v and v.body and v.body:sub(1, 160)))
        return nil
    end
    local captchaToken = v.body:match('"token"%s*:%s*"([^"]+)"')
    if not v.body:match('"status"%s*:%s*"ok"') or not captchaToken then
        log_error("bysekoze: verify rejected head=" .. v.body:sub(1, 200))
        return nil
    end

    -- 2f. playback (заголовок — токен проверки captcha)
    local p = http_post(origin .. "/api/videos/" .. code .. "/embed/playback",
        '{"fingerprint":' .. fpJson .. '}', {
            timeout = EMBED_TIMEOUT,
            headers = {
                ["Content-Type"] = "application/json",
                ["X-Embed-Parent"] = parent,
                ["X-Captcha-Token"] = captchaToken,
            },
        })
    if not p or not p.success or type(p.body) ~= "string" then
        log_error("bysekoze: playback HTTP " .. tostring(p and p.code)
            .. " " .. tostring(p and p.body and p.body:sub(1, 160)))
        return nil
    end

    -- 2g. decrypt -> sources
    local plain = decryptPlayback(p.body)
    if not plain then return nil end
    local url, mime = pickSource(plain)
    if not url or not url:find("^https?://") then
        log_error("bysekoze: bad source url " .. tostring(url))
        return nil
    end
    return url, mime, origin
end

return M
end

__LOADERS["catalog"] = function(...)
-- =====================================================================
-- Lib: catalog/pagination helpers for plugin catalogs: hasNextPage,
--      nextIndex/pageUrl (dominant "?page=N" scheme), urlEncode.
-- Loaded via require_lib("catalog"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.1"

local M = {}

-- =====================================================================
-- Pagination
-- =====================================================================

-- "Has next page" for the dominant scheme where a page is considered
-- non-final as long as it returned any item (39 inline copies of
-- `#items > 0`, plus 7 local hasNextPage helpers with the same body).
-- Plugins that know their total page count keep their own comparison.
function M.hasNextPage(items)
    return type(items) == "table" and #items > 0
end

-- Catalog index is 0-based; pages on the wire are 1-based — the
-- dominant `local page = index + 1` from 74 plugins.
function M.nextIndex(index)
    return (index or 0) + 1
end

-- Build a page URL from a template with "{n}" where the 1-based page
-- number goes. Matches the dominant string-concat schemes:
--   ".../catalog?page={n}"        (guide, most sites)
--   "...&pg={n}"                  (en/scribblehub.lua:33)
--   "...&bpage={n}"               (ru/bookhamster.lua:85)
-- Sites with conditional page params or API cursors keep their own code.
function M.pageUrl(template, index)
    return (template:gsub("{n}", tostring(M.nextIndex(index))))
end

-- =====================================================================
-- Query encoding
-- =====================================================================

-- Pure-Lua mirror of the engine global url_encode (Java
-- URLEncoder.encode(s, "UTF-8"): application/x-www-form-urlencoded —
-- space -> "+", unreserved A-Za-z0-9 . - * _ kept, everything else
-- "%XX" uppercase over UTF-8 bytes, "\n" normalized to "\r\n" first).
-- The 73 plugin call sites use the engine global directly; this copy
-- exists for shared libs and parity tests outside the engine.
-- Byte-wise whitelist: LuaJ's %w matches Latin-1 letters (0xC0-0xFF), so a
-- UTF-8 byte like 0xE3 would stay raw and corrupt the query (CJK/Cyrillic
-- search returned 0). Java URLEncoder keeps only A-Z a-z 0-9 . - * _.
local function unreserved(b)
    return (b >= 48 and b <= 57)
        or (b >= 65 and b <= 90)
        or (b >= 97 and b <= 122)
        or b == 45 or b == 46 or b == 42 or b == 95
end

function M.urlEncode(s)
    if type(s) ~= "string" then return s end
    s = s:gsub("\n", "\r\n")
    return (s:gsub(".", function(c)
        local b = string.byte(c)
        if b == 32 then return "+" end
        if unreserved(b) then return c end
        return string.format("%%%02X", b)
    end))
end

return M
end

__LOADERS["dood"] = function(...)
-- =====================================================================
-- Lib: Doodstream y clones (dsvplay, dood.*)
-- Loaded via require_lib("dood"); uses require_lib("urls").
-- =====================================================================
local version = "1.2.1"

local urls = require_lib("urls")

local M = {}

-- Timeout para peticiones a embebedores (dood pass_md5); the inline copies
-- used 8000-10000 ms, the shared lib keeps the conservative 12000 ms.
local EMBED_TIMEOUT = 12000

-- GET /pass_md5/... from one origin; nil unless the answer is an http(s) URL.
-- The old dood host answers its OWN pass endpoint with an empty 200 after it
-- started redirecting the embed page to the new domain, so "empty" must be
-- treated as failure, not as a valid start string.
local function fetchPass(origin, md5, embedUrl)
    local r = http_get(origin:sub(1, -2) .. md5, { timeout = EMBED_TIMEOUT, headers = { ["Referer"] = embedUrl } })
    if not r.success then return nil end
    local start = r.body:gsub("%s+$", ""):gsub("^%s+", "")
    if not start:find("^https?://") then return nil end
    return start
end

local RANDOM_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

local PASS_MD5_RE = "(/pass_md5/[^'\"]+)"

-- Cloudflare Turnstile gate: the embed page serves the widget and no
-- /pass_md5; only after the play click (level host JS, the Cloudflare
-- iframe itself is untouched) does the reloaded DOM contain /pass_md5/.
-- Fall back to a WebView click on the same URL when the host exposes
-- webview_fetch; without it (JVM tester) the caller sees nil as before.
local function passMd5AfterTurnstile(embedUrl, body)
    if not body:find("turnstile", 1, true) then return nil end
    if type(webview_fetch) ~= "function" then
        log_error("dood: turnstile gate, webview_fetch unavailable")
        return nil
    end
    -- expect включает popup-страховку: если авто-флоу не дал pass_md5,
    -- откроется видимый WebView для ручного прохода Turnstile.
    local html = webview_fetch(embedUrl, {
        click = [[$(".captcha_l").click()]],
        expect = "/pass_md5/",
    })
    if type(html) ~= "string" then
        log_error("dood: turnstile click returned no html")
        return nil
    end
    local md5 = html:match(PASS_MD5_RE)
    if not md5 then log_error("dood: turnstile html has no pass_md5") end
    return md5
end

-- Merged from the four inline copies of resolveDood (ar/anime4up.lua:1377,
-- ar/witanime.lua:1188, id/anichin.lua:656, id/animexin.lua:642) and the
-- former extractDood — the bodies were equivalent; fetching the embed page
-- itself (witanime) belongs to the caller, as does logging (the copies
-- reported "RELOAD"/HTTP status with their own prefixes).
-- Returns url, "mp4", origin of the embed (referer of the final stream),
-- or nil when there is no /pass_md5 (captcha variant) or the round trip
-- failed.
function M.resolveDood(embedUrl, body)
    if type(body) ~= "string" then return nil end
    local md5 = body:match(PASS_MD5_RE)
    if not md5 then md5 = passMd5AfterTurnstile(embedUrl, body) end
    if not md5 then return nil end
    local origin = urls.origin(embedUrl)
    if not origin then return nil end
    local token = md5:match("([^/]+)$")

    local start = fetchPass(origin, md5, embedUrl)
    if not start then
        -- Dood clones rotate domains: the old host still serves the embed
        -- page chain (301) but answers its own /pass_md5/ with an empty 200.
        -- Retry from the origin the embed page actually redirects to
        -- (verified live 2026-10-10: doodstream.com/e/ -> playmogo.com/e/).
        local r = http_get(embedUrl, { timeout = EMBED_TIMEOUT, followRedirects = false })
        local loc = r.headers and r.headers.location and r.headers.location[1]
        if loc then
            local origin2 = urls.origin(urls.resolve(loc, embedUrl))
            if origin2 and origin2 ~= origin then
                start = fetchPass(origin2, md5, embedUrl)
                if start then origin = origin2 end
            end
        end
    end
    if not start then return nil end

    local rnd = {}
    for i = 1, 10 do
        local k = math.random(1, #RANDOM_CHARS)
        rnd[i] = RANDOM_CHARS:sub(k, k)
    end
    local url = start .. table.concat(rnd) .. "?token=" .. tostring(token) .. "&expiry=" .. tostring(os_time())
    return url, "mp4", origin
end

return M
end

__LOADERS["embeds"] = function(...)
-- =====================================================================
-- Lib: dispatcher por servidor (extractFromEmbed).
-- Se carga via require_lib("embeds"); internamente carga las libs de
-- cada embebedor (dood, mixdrop, mp4upload, voe) + urls/hls y usa el API
-- del motor unpack_packed (devuelve "" cuando no hay empaquetador).
-- =====================================================================
local version = "1.3.0"

local urls      = require_lib("urls")
local hls       = require_lib("hls")
local dood      = require_lib("dood")
local mixdrop   = require_lib("mixdrop")
local mp4upload = require_lib("mp4upload")
local voe       = require_lib("voe")
local savefiles = require_lib("savefiles")
local bysekoze  = require_lib("bysekoze")

local M = {}

function M.extractFromEmbed(emb, body)
    local host = urls.hostOf(emb.url)
    local name = (emb.name or ""):lower()

    -- engine contract: unpack_packed returns "" when there is no packer;
    -- nil must never reach the concatenation below (it would be a concat
    -- crash instead of a graceful skip).
    local packed = ""
    if body:find("p,a,c,k,e,d", 1, true) then
        local un = unpack_packed(body)
        if type(un) == "string" and un ~= "" then packed = un end
    end
    local both = urls.unescapeSlashes(packed ~= "" and (packed .. "\n" .. body) or body)

    if host:find("dood") or host:find("dsvplay") or name:find("dsv") or name:find("dood")
        or body:find("/pass_md5/", 1, true) then
        local u, mime, ref = dood.resolveDood(emb.url, body)
        if u then return u, mime, ref end
    end

    if host:find("mp4upload") or name:find("mp4upload") then
        local u, mime, ref = mp4upload.extractMp4upload(both)
        if u then return u, mime, ref end
    end

    if host:find("mixdrop") or host:find("mxdrop") or both:find("MDCore.wurl", 1, true) then
        local u, mime, ref = mixdrop.extractMixdrop(both, emb.url)
        if u then return u, mime, ref end
    end

    if host:find("voe") or name == "voe" then
        local u, mime, ref = voe.extractVoe(emb.url, body)
        if u then return u, mime, ref end
    end

    if host:find("savefiles") or name:find("savefiles") then
        local u, mime, ref = savefiles.extractSavefiles(emb.url)
        if u then return u, mime, ref end
    end

    if host:find("bysekoze") or name:find("bysekoze") then
        local u, mime, ref = bysekoze.extractBysekoze(emb.url)
        if u then return u, mime, ref end
    end

    local u, mime = hls.pickStream(both, emb.url)
    if u then return u, mime, urls.origin(emb.url) end
    return nil
end

return M
end

__LOADERS["fetch"] = function(...)
-- =====================================================================
-- Lib: session-cached page fetch. The engine calls getBookTitle /
-- getBookCoverImageUrl / getBookDescription / getBookGenres /
-- getBookStatus / getBookLastUpdate in parallel, each doing its own
-- http_get(bookUrl) — this module keeps one request per URL.
-- Loaded via require_lib("fetch"). No dependencies on other libs.
--
-- Same contract as the inline fetchPage copies (guide:643):
--   * cache lives for the session only, never for getChapterListHash —
--     that one must always use a direct http_get;
--   * only successful responses are cached, a failed call returns nil
--     and the next call retries;
--   * the cache key is the URL. A non-empty `config` that changes the
--     response body (headers, charset, ...) becomes part of the key, so
--     two configs never share a body.
-- =====================================================================
local version = "1.0.0"

local M = {}

local cache = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

-- Order-independent encoding of a config table, so {a=1,b=2} and {b=2,a=1}
-- share one cache entry. Cycles are not possible here: http_get configs are
-- plain string/number/bool values and one level of headers table.
local function encode(value)
    local t = type(value)
    if t == "table" then
        local keys = {}
        for k in pairs(value) do keys[#keys + 1] = k end
        table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
        local parts = {}
        for _, k in ipairs(keys) do
            parts[#parts + 1] = tostring(k) .. "=" .. encode(value[k])
        end
        return "{" .. table.concat(parts, ";") .. "}"
    end
    return tostring(value)
end

local function keyOf(url, config)
    if type(config) ~= "table" then return url end
    local keys = {}
    for k in pairs(config) do keys[#keys + 1] = k end
    if #keys == 0 then return url end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    local parts = {}
    for _, k in ipairs(keys) do
        parts[#parts + 1] = tostring(k) .. "=" .. encode(config[k])
    end
    return url .. "\0" .. table.concat(parts, ";")
end

-- GET `url` (optional http_get `config`) -> response body or nil.
-- ponytail: no TTL — the plugin session is short-lived and every copy in
-- the repo caches for the whole session (only mtl/wtrlab.lua adds a TTL);
-- add one when a caller actually needs staleness control.
function M.page(url, config)
    if type(url) ~= "string" or url == "" then return nil end
    local key = keyOf(url, config)
    local cached = cache[key]
    if cached ~= nil then return cached end
    local r = http_get(url, config)
    if type(r) ~= "table" or not r.success then
        logErr("fetch: GET failed (HTTP " .. tostring(r and r.code) .. ") " .. url)
        return nil
    end
    cache[key] = r.body
    return r.body
end

-- Drop the whole session cache, or every entry of one URL when given
-- (all config variants of that URL).
function M.clear(url)
    if url == nil then
        cache = {}
        return
    end
    local prefix = url .. "\0"
    for key in pairs(cache) do
        if key == url or key:sub(1, #prefix) == prefix then cache[key] = nil end
    end
end

return M
end

__LOADERS["hls"] = function(...)
-- =====================================================================
-- Lib: stream helpers for videohost extractors: pickStream (generic
--      m3u8/mp4 scan) + hasMediaExt (mime typing of extension-less URLs).
-- Loaded via require_lib("hls"); uses require_lib("urls").
-- =====================================================================
local version = "1.0.0"

local urls = require_lib("urls")

local M = {}

-- =====================================================================
-- Generic stream scan
-- =====================================================================

function M.pickStream(t, embedUrl)
    -- 1) absolute URL
    local hls = t:match([=[(https?://[^"'%s\<>]+%.m3u8[^"'%s\<>]*)]=])
    if hls then return hls, "hls" end

    -- 2) quoted, relative or protocol-relative
    for _, q in ipairs({ '"', "'" }) do
        for s in t:gmatch(q .. "([^" .. q .. "\r\n]+)" .. q) do
            if #s < 600 and not s:find("%s") and s:lower():find(".m3u8", 1, true) then
                return urls.resolve(s, embedUrl), "hls"
            end
        end
    end

    -- 3) direct mp4
    local mp4 = t:match([=[(https?://[^"'%s\<>]+%.mp4[^"'%s\<>]*)]=])
    if mp4 then return mp4, "mp4" end
    for _, q in ipairs({ '"', "'" }) do
        for s in t:gmatch(q .. "(//[^" .. q .. "\r\n]+)" .. q) do
            if #s < 600 and not s:find("%s") and s:lower():find(".mp4", 1, true) then
                return urls.resolve(s, embedUrl), "mp4"
            end
        end
    end
    return nil, nil
end

-- =====================================================================
-- Media extension check
-- =====================================================================

-- Does the URL path (before "?" / "#") end with a media extension?
-- Without it media3 types the stream as progressive and fails on an HLS
-- body (rationale: ar/anime4up.lua:328). Union of the three plugin copies
-- (ar/anime4up.lua:330, ar/animephoenix.lua:45, ar/witanime.lua:1958):
-- .mkv comes from animephoenix and is progressive too, so it must not be
-- typed as "hls".
function M.hasMediaExt(u)
    local base = u:match("^[^%?#]*") or u
    return base:match("%.m3u8$") ~= nil
        or base:match("%.mp4$") ~= nil
        or base:match("%.mkv$") ~= nil
end

return M
end

__LOADERS["meta"] = function(...)
-- =====================================================================
-- Lib: book metadata normalization (rating, update date, status,
--      genre list) shared by the novel extractors.
-- Loaded via require_lib("meta"). No dependencies on other libs.
--
-- Nothing here maps or invents values: an input the site did not really
-- send comes back as nil (plus a log line) so the app shows nothing
-- instead of a made-up number.
-- =====================================================================
local version = "1.0.0"

local M = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

local function trim(s)
    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

-- =====================================================================
-- Rating
-- =====================================================================

-- First number in a rating string -> number in the site's own scale
-- (the app rescales), nil when there is none or it is out of range.
-- Covers the formats used by the getBookRating copies: "4.6" (bare
-- number / data-rating attribute), "8/10", "Rating: 7.5/10", "Rating: 9",
-- "Rank: 3" and the comma decimal separator ("4,6" = 4.6).
function M.rating(str)
    if type(str) ~= "string" then return nil end
    local n = str:match("(%d+[%.,]%d+)") or str:match("(%d+)")
    if not n then
        logErr("meta.rating: no number in " .. str:sub(1, 60))
        return nil
    end
    local v = tonumber((n:gsub(",", ".")))
    if not v or v < 0 or v > 10 then
        logErr("meta.rating: out of 0..10 range: " .. str:sub(1, 60))
        return nil
    end
    return v
end

-- =====================================================================
-- Last update date
-- =====================================================================

-- Relative "N <unit> ago" — EN from the normalizeUpdateDate copies
-- (en/novelphoenix.lua:305, en/freewebnovel.lua, en/lightnovelpub.lua,
-- en/wuxiabox.lua, mtl/sonicmtl.lua), RU from ru/ifreedom.lua:120 and
-- ru/jaomix.lua (which matches the unit as a substring, so plurals and
-- the odd abbreviation keep working). Months/years are approximate
-- (30/365 days), as in those copies.
local REL_EN = {
    second = 1, seconds = 1,
    minute = 60, minutes = 60,
    hour = 3600, hours = 3600,
    day = 86400, days = 86400,
    week = 604800, weeks = 604800,
    month = 2592000, months = 2592000,
    year = 31536000, years = 31536000,
}

local REL_RU = {
    { "секунд", 1 }, { "сек", 1 }, { "минут", 60 }, { "мин", 60 },
    { "час", 3600 }, { "ч", 3600 }, { "дн", 86400 },
    { "недел", 604800 }, { "нед", 604800 },
    { "месяц", 2592000 }, { "мес", 2592000 },
    { "год", 31536000 }, { "лет", 31536000 }, { "г", 31536000 },
}

local function relativeDate(str)
    local n, unit = str:match("(%d+)%s+([%a]+)%s+ago")
    if n then
        local secs = REL_EN[unit]
        if not secs then return nil end
        return os.date("%Y-%m-%d", os.time() - tonumber(n) * secs)
    end
    local num, word = str:match("(%d+)%s*([^%d%s]+)%s+назад")
    if not num then return nil end
    for _, pair in ipairs(REL_RU) do
        if word:find(pair[1], 1, true) then
            return os.date("%Y-%m-%d", os.time() - tonumber(num) * pair[2])
        end
    end
    return nil
end

-- Any date-ish string -> "YYYY-MM-DD" or nil (guide:277). Recognized:
-- ISO 8601 anywhere in the string ("2026-08-18T23:00:15.751Z") and the
-- relative forms above ("Updated 3 days ago", "3 дня назад"). Anything
-- else (month names, DD.MM.YY, site-specific wording) is deliberately
-- not guessed — pass the site's own format from the plugin.
function M.normalizeDate(str)
    if type(str) ~= "string" or str == "" then return nil end
    local y, m, d = str:match("(%d%d%d%d)%-(%d%d)%-(%d%d)")
    if y then return y .. "-" .. m .. "-" .. d end
    local rel = relativeDate(str)
    if rel then return rel end
    logErr("meta.normalizeDate: unrecognized " .. str:sub(1, 60))
    return nil
end

-- =====================================================================
-- Status
-- =====================================================================

-- Status text is shown by the app as-is (guide:264) — no mapping, no
-- case folding by default: plugins return the site's own string. Pass
-- { lower = true } only when the plugin really wants a lowercase label
-- (en/novelfire.lua is the only copy that lowercases).
function M.status(str, opts)
    if type(str) ~= "string" then return nil end
    local s = trim((str:gsub("%s+", " ")))
    if s == "" then return nil end
    if opts and opts.lower then
        if type(string_lower) == "function" then
            s = string_lower(s)
        else
            s = s:lower()
        end
    end
    return s
end

-- =====================================================================
-- Genres
-- =====================================================================

-- Collects genre names out of the elements returned by html_select (or
-- plain strings) — the shared inner loop of the getBookGenres copies
-- (e.g. ar/mangalik.lua:125, ru/allhentai.lua:179): trim/clean the label,
-- drop empties, drop duplicates, keep the site order. The selector and
-- the data source stay in the plugin.
function M.collectGenres(anchors, opts)
    local out, seen = {}, {}
    if type(anchors) ~= "table" then return out end
    for _, el in ipairs(anchors) do
        local raw
        if type(el) == "string" then
            raw = el
        elseif type(el) == "table" then
            raw = el.text
        end
        if type(raw) == "string" and raw ~= "" then
            local name
            if opts and opts.clean and type(string_clean) == "function" then
                name = string_clean(raw)
            elseif type(string_trim) == "function" then
                name = string_trim(raw)
            else
                name = trim(raw)
            end
            if name ~= "" and not seen[name] then
                seen[name] = true
                out[#out + 1] = name
            end
        end
    end
    return out
end

return M
end

